// Extract parameters safely from Retell or test payload
const raw = $input.first().json;
const body = raw.body || raw;
const args = body.args || body;

const rawSlot = String(args.desired_slot || args.time || "2:30 PM").toLowerCase();
const patientName = String(args.patient_name || args.name || "Valued Patient").trim();
let phone = String(args.phone_number || args.phone || "+15550199000").replace(/[^\d+]/g, "");
if (!phone.startsWith("+")) phone = "+1" + phone;
const rawReason = String(args.reason || "General Checkup").toLowerCase();

// SCENARIO 3: HIPAA PHI Sanitization & De-identification
let sanitizedCategory = "General Consultation & Checkup";
if (rawReason.includes("clean") || rawReason.includes("hygiene") || rawReason.includes("plaque")) {
  sanitizedCategory = "Routine Dental Hygiene & Cleaning";
} else if (rawReason.includes("pain") || rawReason.includes("toothache") || rawReason.includes("emergency") || rawReason.includes("broken")) {
  sanitizedCategory = "Priority Diagnostic Triage";
} else if (rawReason.includes("whiten") || rawReason.includes("cosmetic")) {
  sanitizedCategory = "Cosmetic Consultation";
}

// Parse time strictly (must have :MM or am/pm so date numbers like "Nov 11" or "17" are ignored)
let hour = 14, minute = 30;
const match = rawSlot.match(/(\d{1,2}):(\d{2})\s*(am|pm)?|(\d{1,2})\s*(am|pm)/i);
if (match) {
  let rawMin = 0;
  let ampm = "";
  if (match[1]) {
    hour = parseInt(match[1], 10);
    rawMin = parseInt(match[2], 10);
    ampm = (match[3] || "").toLowerCase();
  } else {
    hour = parseInt(match[4], 10);
    ampm = (match[5] || "").toLowerCase();
  }

  if (ampm === "pm" && hour < 12) hour += 12;
  if (ampm === "am" && hour === 12) hour = 0;
  if (!ampm && hour >= 1 && hour <= 6) hour += 12;

  if (rawMin < 15) minute = 0;
  else if (rawMin < 45) minute = 30;
  else { minute = 0; hour += 1; }
}

// SCENARIO 2: Collision Detection using true parsed hour (12:00 PM - 1:00 PM ET)
const isLunchConflict = (hour === 12) || rawSlot.includes("noon");

const dateStr = "2026-11-17";
const pad = (n) => String(n).padStart(2, "0");
const startTime = `${dateStr}T${pad(hour)}:${pad(minute)}:00-05:00`;
let endMin = minute + 30;
let endHr = hour;
if (endMin >= 60) { endHr += 1; endMin -= 60; }
const endTime = `${dateStr}T${pad(endHr)}:${pad(endMin)}:00-05:00`;

const dispHr = hour > 12 ? hour - 12 : (hour === 0 ? 12 : hour);
const dispAmPm = hour >= 12 ? "PM" : "AM";
const cleanTimeLabel = `${dispHr}:${pad(minute)} ${dispAmPm}`;

return [{
  json: {
    patient_name: patientName,
    phone_number: phone,
    requested_slot: rawSlot,
    sanitized_category: sanitizedCategory,
    is_conflict: isLunchConflict,
    confirmed_slot: isLunchConflict ? null : cleanTimeLabel,
    start_time_iso: startTime,
    end_time_iso: endTime,
    alternate_slots: ["2:30 PM", "3:30 PM"],
    timestamp: new Date().toISOString()
  }
}];
